use std::fs

fn eval(line: string) -> string {
    let mut st: Vec<int> = []
    for tok in line.split(" ") {
        if tok == "+" || tok == "-" || tok == "*" || tok == "/" {
            if st.len() < 2 {
                return "error: underflow"
            }
            let b = st.pop().unwrap_or(0)
            let a = st.pop().unwrap_or(0)
            if tok == "+" {
                st.push(a + b)
            } else if tok == "-" {
                st.push(a - b)
            } else if tok == "*" {
                st.push(a * b)
            } else {
                if b == 0 {
                    return "error: divzero"
                }
                st.push(a / b)
            }
        } else {
            if tok.starts_with("+") {
                return "error: token"
            }
            match tok.parse::<int>() {
                Ok(n) => {
                    st.push(n)
                }
                Err(_) => {
                    return "error: token"
                }
            }
        }
    }
    if st.len() != 1 {
        return "error: leftover"
    }
    "${st[0]}"
}

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    for raw in text.lines() {
        let line = raw.trim()
        if line.len() == 0 {
            continue
        }
        println(eval(line))
    }
}

